import{_ as e,a}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as n}from"./chunks/ts-mic-privacy.DXgfNaDe.js";import{_ as o,o as r,c as i,ag as s}from"./chunks/framework.DTisvaUJ.js";const y=JSON.parse('{"title":"Troubleshooting — No audio or recognition","description":"Fix missing speech audio, microphone recognition and VRChat chatbox output in Mutelink with step-by-step checks.","frontmatter":{"title":"Troubleshooting — No audio or recognition","description":"Fix missing speech audio, microphone recognition and VRChat chatbox output in Mutelink with step-by-step checks.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/help/troubleshooting"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Troubleshooting — No audio or recognition | Mutelink"}],["meta",{"property":"og:description","content":"Fix missing speech audio, microphone recognition and VRChat chatbox output in Mutelink with step-by-step checks."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/help/troubleshooting"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Troubleshooting — No audio or recognition | Mutelink"}],["meta",{"name":"twitter:description","content":"Fix missing speech audio, microphone recognition and VRChat chatbox output in Mutelink with step-by-step checks."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}]]},"headers":[],"relativePath":"en/help/troubleshooting.md","filePath":"en/help/troubleshooting.md"}'),d={name:"en/help/troubleshooting.md"};function h(l,t,c,u,p,g){return r(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="困ったときの対処" tabindex="-1">Troubleshooting <a class="header-anchor" href="#困ったときの対処" aria-label="Permalink to &quot;Troubleshooting {#困ったときの対処}&quot;">​</a></h1><p>Try these checks from top to bottom. If your issue is not listed, report it through Settings &gt; Other &gt; About &gt; Send feedback.</p><h2 id="読み上げの声が出ない" tabindex="-1">No synthesized speech <a class="header-anchor" href="#読み上げの声が出ない" aria-label="Permalink to &quot;No synthesized speech {#読み上げの声が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Speech synthesis button on the main screen</td><td>Turn it on; no speech is produced while off</td></tr><tr><td>Voice selected</td><td>Select VOICEVOX, Irodori-TTS or Qwen3-TTS for the output language. None sends only to the chatbox</td></tr><tr><td>Voice downloaded</td><td>Check Settings &gt; Other &gt; Models and storage. Also select a character for VOICEVOX</td></tr><tr><td>Output devices and volume</td><td>Check Speakers under Settings &gt; Sending &gt; Speech basics, including per-device volume</td></tr><tr><td>Reading translated text</td><td>Requires the <a href="/Mutelink-releases/en/about/supporter">supporter edition</a>; without it, only the chatbox receives translations</td></tr><tr><td>Supported output language</td><td>VOICEVOX/Irodori are Japanese-only; Qwen supports 10 languages. Without a suitable voice, text goes only to chatbox</td></tr><tr><td>“AI voice disabled because VRAM is full”</td><td>Speech was disabled automatically and text goes to chatbox. It will not resume automatically; turn TTS on once memory is available to restore the same voice</td></tr></tbody></table><h2 id="vrchatの相手に声が届かない" tabindex="-1">Others in VRChat cannot hear the voice <a class="header-anchor" href="#vrchatの相手に声が届かない" aria-label="Permalink to &quot;Others in VRChat cannot hear the voice {#vrchatの相手に声が届かない}&quot;">​</a></h2><p>Use these checks if you hear synthesis locally but others do not.</p><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Virtual Cable installed</td><td>Check CABLE Input/Output in Windows sound settings; <a href="/Mutelink-releases/en/guide/getting-started#_1-vb-audio-virtual-cableを入れる">install if missing</a></td></tr><tr><td>CABLE Input selected in Mutelink</td><td>Select it in Settings &gt; Sending &gt; Speech basics &gt; Speakers. Refresh devices or restart Mutelink if missing</td></tr><tr><td>VRChat microphone set to CABLE Output</td><td>Check VRChat Settings &gt; Audio</td></tr><tr><td><strong>Reselect the VRChat microphone</strong></td><td>Even if CABLE Output is selected, switch to another device and back. VRChat keeps its startup device until reselected; restarting VRChat also works</td></tr><tr><td>VRChat microphone muted</td><td>Unmute it in VRChat</td></tr><tr><td>CABLE Output chosen as Mutelink microphone</td><td>Select your physical microphone in Mutelink instead</td></tr></tbody></table><p><img src="'+e+'" alt="VRChat microphone set to CABLE Output"></p><h2 id="自分には読み上げが聞こえない" tabindex="-1">I cannot hear my synthesized voice <a class="header-anchor" href="#自分には読み上げが聞こえない" aria-label="Permalink to &quot;I cannot hear my synthesized voice {#自分には読み上げが聞こえない}&quot;">​</a></h2><p>With only CABLE Input selected, others hear the voice but you do not. In Settings &gt; Sending &gt; Speech basics &gt; Speakers, select both CABLE Input and your headphones/speakers. Adjust their volumes separately.</p><h2 id="vrchatに文字が出ない" tabindex="-1">No text in VRChat <a class="header-anchor" href="#vrchatに文字が出ない" aria-label="Permalink to &quot;No text in VRChat {#vrchatに文字が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>OSC enabled</td><td>Action Menu &gt; Options &gt; OSC &gt; Enabled</td></tr><tr><td>Main-screen chatbox button</td><td>Turn it on to send chatbox messages</td></tr><tr><td>Text actually sent</td><td>With automatic sending off, recognition alone does not send text. Use Send</td></tr><tr><td>Waiting for speech to start</td><td>“Show when speech starts” under Settings &gt; Sending &gt; Speech basics delays text until speech begins (up to 8 seconds)</td></tr><tr><td>Chatbox hidden in VRChat</td><td>Check VRChat’s own settings</td></tr></tbody></table><p><img src="'+a+'" alt="VRChat OSC Enabled"></p><h2 id="音声認識が動かない・途切れる" tabindex="-1">Recognition does not work or cuts out <a class="header-anchor" href="#音声認識が動かない・途切れる" aria-label="Permalink to &quot;Recognition does not work or cuts out {#音声認識が動かない・途切れる}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Recognition enabled</td><td>Turn on the main-screen recognition button</td></tr><tr><td>Correct microphone</td><td>Settings &gt; Speaking &gt; Microphone: select the microphone you speak into</td></tr><tr><td>Windows microphone access</td><td>Settings &gt; Privacy &amp; security &gt; Microphone: allow desktop apps to access the microphone</td></tr><tr><td>Model downloaded</td><td>Local engines need an initial download; check Settings &gt; Other &gt; Models and storage</td></tr><tr><td>Cannot connect to recognition service</td><td>Cloud services may fail due to network/provider issues. Select a local engine in Settings &gt; Speaking &gt; Language and recognition (<a href="/Mutelink-releases/en/compare/speech-recognition">comparison</a>)</td></tr><tr><td>Engine supports the language</td><td>Parakeet Japanese TDT/Haas-ja are Japanese-only; Parakeet English cannot recognize Japanese</td></tr><tr><td>Only certain words missing</td><td>Check whether they are in excluded words</td></tr></tbody></table><p><img src="'+n+'" alt="Windows microphone privacy settings"></p><h2 id="ダウンロードが失敗する" tabindex="-1">Downloads fail <a class="header-anchor" href="#ダウンロードが失敗する" aria-label="Permalink to &quot;Downloads fail {#ダウンロードが失敗する}&quot;">​</a></h2><p>The error reason appears on screen. Partial downloads are kept; press Download again to resume.</p><table tabindex="0"><thead><tr><th>Message</th><th>Action</th></tr></thead><tbody><tr><td>Connection lost or stalled</td><td>Check your network and try again</td></tr><tr><td>File missing at provider</td><td>The download location may have changed. Update the app (Settings &gt; Other &gt; About)</td></tr><tr><td>Provider not responding</td><td>May be temporary; wait and retry</td></tr><tr><td>Corrupt file</td><td>It was deleted automatically; download again</td></tr><tr><td>Not enough disk space</td><td>Free space and retry. Check sizes in Settings &gt; Other &gt; Models and storage</td></tr></tbody></table><p>Delete partial downloads in Settings &gt; Other &gt; Models and storage.</p><h2 id="irodori-tts・qwen3-ttsが動かない" tabindex="-1">Irodori-TTS or Qwen3-TTS does not work <a class="header-anchor" href="#irodori-tts・qwen3-ttsが動かない" aria-label="Permalink to &quot;Irodori-TTS or Qwen3-TTS does not work {#irodori-tts・qwen3-ttsが動かない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Vulkan support</td><td>A Vulkan-compatible GPU and driver are needed. Update your GPU driver</td></tr><tr><td>Available VRAM</td><td>Shared with VRChat and local translation. Lower VRChat graphics, run translation on CPU or use VOICEVOX</td></tr><tr><td>First utterance is slow</td><td>Model loading takes time after startup or voice switching</td></tr><tr><td>Slow engine switching</td><td>Only one Irodori/Qwen engine is loaded at a time. Changing output language may take several seconds</td></tr></tbody></table><h2 id="翻訳されない" tabindex="-1">Translation does not happen <a class="header-anchor" href="#翻訳されない" aria-label="Permalink to &quot;Translation does not happen {#翻訳されない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Different input/output languages</td><td>Translation occurs only when spoken and output languages differ</td></tr><tr><td>Engine ready</td><td>Enter an Azure key or download PLaMo/TranslateGemma in Settings &gt; Translation (<a href="/Mutelink-releases/en/compare/translation">comparison</a>)</td></tr><tr><td>Azure key and region</td><td>See <a href="/Mutelink-releases/en/guide/azure-translator#うまくいかないとき">Azure setup troubleshooting</a></td></tr><tr><td>Translation appears but no voice</td><td>Reading translations requires the <a href="/Mutelink-releases/en/about/supporter">supporter edition</a> and a compatible voice (Qwen for non-Japanese)</td></tr></tbody></table><p>On translation failure, an error is shown and only the original text is sent to the chatbox.</p><h2 id="聞こえた声が出ない" tabindex="-1">Incoming speech does not appear <a class="header-anchor" href="#聞こえた声が出ない" aria-label="Permalink to &quot;Incoming speech does not appear {#聞こえた声が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>Listening enabled</td><td>Start with the main-screen 👂 button</td></tr><tr><td>VRChat running</td><td>Only the app selected in Settings &gt; Listening &gt; Incoming speech (VRChat by default) is captured. Otherwise, it waits for that app to start</td></tr><tr><td>Model downloaded</td><td>Check Settings &gt; Other &gt; Models and storage</td></tr><tr><td>Continuous BGM</td><td>It may prevent utterance boundaries. Increase voice-detection strictness in Settings &gt; Listening &gt; Incoming speech</td></tr><tr><td>Your synthesized speech missing</td><td>Mutelink’s own speech is deliberately excluded</td></tr></tbody></table><h2 id="vrの中に画面が出ない" tabindex="-1">No panels in VR <a class="header-anchor" href="#vrの中に画面が出ない" aria-label="Permalink to &quot;No panels in VR {#vrの中に画面が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Action</th></tr></thead><tbody><tr><td>SteamVR running</td><td>Mutelink reconnects every few seconds. Restart Mutelink with SteamVR open if needed</td></tr><tr><td>Other overlay apps</td><td>Check controller-button conflicts with other SteamVR overlays</td></tr><tr><td>Attach to hands</td><td>Requires the <a href="/Mutelink-releases/en/about/supporter">Customization supporter extension</a>. Without it, panels stay in your view</td></tr></tbody></table><h2 id="アプリが起動しない" tabindex="-1">The app will not start <a class="header-anchor" href="#アプリが起動しない" aria-label="Permalink to &quot;The app will not start {#アプリが起動しない}&quot;">​</a></h2><p>Reinstall the latest version and restart Windows. If it still fails, contact the developer through BOOTH or X (<a href="https://x.com/nktssbat" target="_blank" rel="noreferrer">@nktssbat</a>, <a href="https://x.com/yuki54625" target="_blank" rel="noreferrer">@yuki54625</a>).</p>',31)])])}const f=o(d,[["render",h]]);export{y as __pageData,f as default};
